const refreshItem = (s) => {
    const comp = 'SET_' + s.key.toUpperCase();
    if (s.type === 'bool') return Promise.all([ui.text(comp, s.label), ui.checked(comp, !!settings.get(s.key))]);
    if (values(s)) {
        const rows = s.type === 'number' && s.displayUnit
            ? Promise.all(values(s).map((v, i) => ui.text(comp, numberLabel(s, v, (k) => settings.get(k)), i, 'ItemText')))
            : Promise.resolve();
        return rows.then(() => ui.selected(comp, Math.max(0, values(s).indexOf(settings.get(s.key)))));
    }
    // other types: two-row buttons in the wide settings state, label above, value below
    return ui.cells(comp, 0, { Text1stRow: s.label, Text2ndRow: settings.display(s.key) });
};
const refresh = () => Promise.all(schema.map(refreshItem));
settings.onChange((key) => {
    Promise.all(schema.filter((s) => s.displayUnit && s.displayUnit.setting === key).map(refreshItem))
        .catch((e) => ctx.log.error(e));
});

